<script setup lang="ts">
import { ref } from 'vue';import type { ViewModel } from '../app/useWorkspace';import type {Memory} from '../domain/contracts';
const props=defineProps<{w:ViewModel}>();const text=ref(''),editing=ref<string>(),query=ref(''),results=ref<Memory[]>();
function begin(m:Memory){text.value=m.record?m.annotation||'':m.text;editing.value=m.id;}
async function save(){await props.w.saveMemory(text.value,editing.value);text.value='';editing.value=undefined;results.value=undefined;}
async function search(){results.value=await props.w.searchMemory(query.value);}
function source(id:string){props.w.panel='story';setTimeout(()=>document.getElementById(`turn-${id}`)?.scrollIntoView({block:'center'}),100);}
</script>
<template><section class="surface"><header class="panel-heading"><div><p class="eyebrow">MEMORY / 记忆</p><h1>记忆</h1></div><span class="tag">{{w.memories.length}} 条有效记忆</span></header>
  <div class="actions"><button v-if="w.pendingMemoryCount" :disabled="w.busy||w.workingMemory" @click="w.retryMemory()">补记 {{w.pendingMemoryCount}} 条</button><button v-if="w.workingMemory" @click="w.stopMemory()">停止</button><label class="toggle"><input v-model="w.preferences.vectorEnabled" type="checkbox" :disabled="w.busy||w.workingMemory||(w.preferences.mode==='server'&&w.localService?.capabilities.embeddings===false)" />向量检索</label><button :disabled="!w.preferences.vectorEnabled||w.busy||w.workingMemory||(w.preferences.mode==='server'&&w.localService?.capabilities.embeddings===false)" @click="w.indexMemories()">{{w.workingMemory?'正在建立索引…':'生成缺失向量'}}</button></div>
  <form class="search-row" @submit.prevent="search"><label>检索记忆<input v-model="query" placeholder="输入人物或关键词" /></label><button type="submit" :disabled="w.busy||w.workingMemory">检索</button><button type="button" @click="query='';results=undefined">显示全部</button></form>
  <form @submit.prevent="save"><label>{{editing?(w.memories.find(m=>m.id===editing)?.record?'补充记忆':'编辑记忆'):'添加手记'}}<textarea v-model="text" rows="3" :maxlength="editing&&w.memories.find(m=>m.id===editing)?.record?3000:6000" :required="!editing||!w.memories.find(m=>m.id===editing)?.record" /></label><div class="actions"><button class="primary" type="submit" :disabled="w.busy||w.workingMemory">{{editing?'保存记忆':'添加手记'}}</button><button v-if="editing" type="button" @click="editing=undefined;text=''">取消编辑</button></div></form>
  <div class="memory-list"><article v-for="m in (results??w.memories)" :key="m.id" class="list-entry"><header><span class="tag">{{m.kind==='note'?'手记':m.kind==='chapter'?'章节摘要':'事件记忆'}}</span><small class="muted">{{w.vectorStatus(m)}}</small></header><p>{{m.kind==='event'&&!m.record?'本轮记忆待补记。':m.text}}</p><p v-if="m.error" class="model-list-error">{{m.error}}</p><p v-if="m.indexError" class="model-list-error">{{m.indexError}}</p><div class="actions"><button v-if="m.kind==='event'&&m.status!=='ready'" :disabled="w.busy||w.workingMemory" @click="w.retryMemory(m.id)">补记</button><button v-if="m.kind!=='event'||m.record" :disabled="w.busy||w.workingMemory" @click="begin(m)">{{m.record?'补充':'编辑'}}</button><button :disabled="w.busy||w.workingMemory" @click="w.removeMemory(m.id);results=undefined">删除</button><button v-if="m.sourceTurn" @click="source(m.sourceTurn)">查看来源</button></div></article><p v-if="!(results??w.memories).length" class="empty">暂无匹配记忆。</p></div>
</section></template>


